mapper.select:
SELECT b.*, m.BBS_NM
FROM LETTNBBS b
LEFT JOIN LETTNBBSMASTER m ON b.BBS_ID = m.BBS_ID
WHERE b.BBS_ID = #{bbsId}
  AND b.NTT_ID = #{nttId}

mapper.insert:
INSERT INTO LETTNBBS (
    BBS_ID, NTT_ID, NTT_SJ, NTT_CN, NTCR_NM, NOTICE_AT, ATCH_FILE_ID, FRST_REGIST_PNTTM
) VALUES (
    #{bbsId, jdbcType=VARCHAR}, #{nttId, jdbcType=BIGINT}, #{nttSj, jdbcType=VARCHAR}, #{nttCn, jdbcType=VARCHAR}, #{ntcrNm, jdbcType=VARCHAR}, #{noticeAt, jdbcType=VARCHAR}, #{atchFileId, jdbcType=VARCHAR}, #{frstRegistPnttm, jdbcType=TIMESTAMP}
)

mapper.update:
UPDATE LETTNBBS

    NTT_SJ = #{nttSj, jdbcType=VARCHAR},
    NTT_CN = #{nttCn, jdbcType=VARCHAR},
    NTCR_NM = #{ntcrNm, jdbcType=VARCHAR},
    NOTICE_AT = #{noticeAt, jdbcType=VARCHAR},
    ATCH_FILE_ID = #{atchFileId, jdbcType=VARCHAR},
    FRST_REGIST_PNTTM = #{frstRegistPnttm, jdbcType=TIMESTAMP}

WHERE BBS_ID = #{bbsId}
  AND NTT_ID = #{nttId}

UPDATE LETTNBBS
   SET USE_AT = 'N'
 WHERE BBS_ID = #{bbsId}
   AND NTT_ID = #{nttId}

UPDATE LETTNBBS
   SET RDCNT = COALESCE(RDCNT, 0) + 1
 WHERE BBS_ID = #{bbsId}
   AND NTT_ID = #{nttId}

mapper.select:
SELECT CASE WHEN EXISTS (
           SELECT 1
             FROM LETTNBBSUSE
            WHERE BBS_ID = #{bbsId}
              AND USE_AT = 'Y'
       ) THEN 'Y' ELSE 'N' END
